`,e.jsx(t.p,{children:'The next phase is a thin backend (Node + SQLite + WebSocket) for live mode, so a run can stream into the UI in real time as it executes - bars growing toward "now," tokens arriving live. After that: a WebGL renderer to push past 500k spans, and an eval overlay to compare scores across a cohort of runs.'})]})}function Re(n={}){const{wrapper:t}={...i(),...n.components};return t?e.jsx(t,{...n,children:e.jsx(f,{...n})}):f(n)}const vt=Object.freeze(Object.defineProperty({__proto__:null,default:Re,frontmatter:Oe},Symbol.toStringTag,{value:"Module"})),De={title:"AgentOps RAG",slug:"agentops-rag",description:"A production-style agentic retrieval platform with tenant isolation, async ingestion, DLQ replay, evals, traces, rate limits, benchmarks, and citation-grounded refusals.",kind:"personal",link:"https://github.com/shusingh/agentops-rag",repo:"https://github.com/shusingh/agentops-rag",tags:["Python","FastAPI","OpenSearch","Redis","Postgres","OpenTelemetry","RAG"],year:2026,status:"released",featured:!0,order:1,stat:{number:"8+",label:"production concerns modeled"},diagram:{nodes:["FastAPI","tenant auth","ingestion queue","agent runtime","evals + traces"],caption:"The project treats RAG as an operational system, not a chatbot demo: auth, ingestion, retrieval, critique, refusal, and observability are first-class paths."}};function x(n){const t={a:"a",code:"code",h2:"h2",li:"li",p:"p",strong:"strong",ul:"ul",...i(),...n.components};return e.jsxs(e.Fragment,{children:[e.jsx(t.h2,{id:"system-intent",children:e.jsx(t.a,{href:"#system-intent",children:"System intent"})}),`
`,e.jsx(t.p,{children:"AgentOps RAG is a production-style retrieval platform for agentic applications. The point is not to prove that a model can answer questions from documents. The point is to show the infrastructure an engineering team needs before trusting retrieval in a multi-tenant product: tenant boundaries, async ingestion, replayable failures, grounded answers, evals, traces, rate limits, and benchmarks."}),`
`,e.jsx(t.p,{children:"The repo is intentionally explicit. It avoids hiding the runtime behind a large agent framework so the important system boundaries stay visible."}),`
`,e.jsx(d,{groups:[{title:"API boundary",items:["FastAPI","JWT tenant claims","endpoint rate limits"]},{title:"Data plane",items:["Redis Streams","Postgres metadata","OpenSearch BM25 + vector"]},{title:"Agent plane",items:["planner","retriever tool","coverage critic","finalizer"]}],caption:"The project separates request handling, ingestion/storage, and agent execution so each layer has a clear owner and failure model."}),`
`,e.jsx(t.h2,{id:"requirements",children:e.jsx(t.a,{href:"#requirements",children:"Requirements"})}),`
`,e.jsx(t.p,{children:"The system is designed around five non-negotiable requirements:"}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsx(t.li,{children:"A tenant must never read another tenant's documents or replay another tenant's failed jobs."}),`
`,e.jsx(t.li,{children:"Ingestion failures must be inspectable and replayable without losing the original request context."}),`
`,e.jsx(t.li,{children:"Answers must be citation-grounded, or the system should refuse instead of inventing support."}),`
`,e.jsx(t.li,{children:"Operators need traces and eval reports, not just server logs."}),`
`,e.jsx(t.li,{children:"Expensive endpoints need rate limits with explicit degraded behavior when Redis is unavailable."}),`
`]}),`
`,e.jsx(t.p,{children:"These requirements shape the architecture more than the model choice does."}),`
`,e.jsx(t.h2,{id:"high-level-design",children:e.jsx(t.a,{href:"#high-level-design",children:"High-level design"})}),`
`,e.jsx(l,{nodes:["upload document","enqueue ingestion job","chunk + index","ask question","retrieve evidence","critic validates","answer or refuse"],caption:"Documents move through an async ingestion path. Questions move through a bounded agent path with citation checks before finalization."}),`
`,e.jsxs(t.p,{children:["The write path starts at ",e.jsx(t.code,{children:"POST /documents"}),". The API validates the JWT, derives tenant ID from claims, stores metadata in Postgres, and enqueues an ingestion job in Redis Streams. The worker chunks the document, indexes chunks into OpenSearch, updates document state, and writes failed jobs to a DLQ with tenant ID, document ID, stage, and retry count."]}),`
`,e.jsxs(t.p,{children:["The read path starts at ",e.jsx(t.code,{children:"POST /ask"}),". The endpoint applies tenant-scoped rate limits, runs the planner, executes tenant-filtered retrieval, sends retrieved evidence to the critic, and finalizes either a grounded answer or a refusal. Every answer includes a trace ID."]}),`
`,e.jsx(t.h2,{id:"design-decisions",children:e.jsx(t.a,{href:"#design-decisions",children:"Design decisions"})}),`
`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Tenant ID comes from JWT claims, not request bodies."})," This prevents a client from asking for another tenant by changing payload fields. The same rule applies to document listing, retrieval, and DLQ replay."]}),`
`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Retrieval is hybrid by default."})," BM25 handles exact names, IDs, and policy terms. Vector search handles semantic similarity. The runtime fuses the evidence instead of trusting one retrieval mode for every question."]}),`
`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Refusal is a product behavior."})," If the critic cannot verify citation coverage, the finalizer returns a refusal. That is preferable to a confident answer with weak support."]}),`
`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"DLQ replay is scoped."})," Failed ingestion jobs keep tenant and document metadata, so an operator can replay the right work without rerunning the whole corpus."]}),`
`,e.jsx(t.h2,{id:"operational-behavior",children:e.jsx(t.a,{href:"#operational-behavior",children:"Operational behavior"})}),`
