`,e.jsx(t.h2,{id:"design-decisions",children:e.jsx(t.a,{href:"#design-decisions",children:"Design decisions"})}),`
`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Keep inference server-side."})," This protects provider details, avoids leaking API keys, and keeps prompt and parsing logic out of the browser."]}),`
`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Normalize before rendering."})," The model can produce messy text. The UI should receive sections, days, activities, and notes in a predictable shape."]}),`
`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Design for cold starts."})," The backend runs as a Vercel serverless function, so an idle instance adds latency to the first request. The UI needs a real loading state rather than pretending generation is instant."]}),`
